contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint dep, uint minSum, uint am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (dep)); require(dep <= 1000000000000000000000000000000);
        require(address(this).balance >= dep, "not enough balance");
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.SetMinSum(minSum); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Deposit{value: dep}(); if (__ESBMC_reverted()) return;

        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;

        bool allowed = balBefore >= minSum && balBefore >= am;
        assert(reverted != allowed || (!reverted && balAfter == balBefore - am) || (!allowed && balAfter == balBefore));
    }

    receive() external payable {}
}

