    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 dep, uint256 minSum, uint256 am) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= dep);
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.SetMinSum(minSum) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: dep}() {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfter;
        try c.balances(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        bool allowed = balBefore >= minSum && balBefore >= am;
        assertTrue(reverted != allowed || (!reverted && balAfter == balBefore - am) || (!allowed && balAfter == balBefore));
    }

    function testFuzz_run(uint256 dep, uint256 minSum, uint256 am) public {
        _run(dep, minSum, am);
    }

